<?php require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';?><main class="container-fluid py-4 px-lg-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="mb-0"><?=esAdministrador()?'Rendiciones':'Mis rendiciones'?></h2><span class="text-secondary">Dinero declarado y estado de revisión.</span></div><a class="btn btn-primary" href="index.php?c=rendicion&a=crear">+ Nueva rendición</a></div><div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Fecha</th><?php if(esAdministrador()):?><th>Vendedor</th><?php endif;?><th>Campaña</th><th>Monto</th><th>Estado</th><th>Observación / pagos</th><?php if(esAdministrador()):?><th>Revisar</th><?php endif;?></tr></thead><tbody><?php if(!$rendiciones):?><tr><td colspan="7" class="vacio">No hay rendiciones registradas.</td></tr><?php else:foreach($rendiciones as $r):?><tr><td><?=e($r['fecha_rendicion'])?></td><?php if(esAdministrador()):?><td><?=e($r['vendedor'])?></td><?php endif;?><td><?=e($r['campania'])?></td><td>$<?=number_format($r['monto_declarado'],2,',','.')?></td><td><span class="badge text-bg-<?=$r['estado']==='APROBADA'?'success':($r['estado']==='OBSERVADA'?'danger':'warning')?>"><?=e($r['estado'])?></span></td><td><?=e($r['observacion'])?><small class="d-block text-secondary">Pagos: <?=e($r['pagos_ids'])?></small></td><?php if(esAdministrador()):?><td><form method="post" action="index.php?c=rendicion&a=estado" class="d-flex gap-2"><input type="hidden" name="id" value="<?=$r['id']?>"><select class="form-select form-select-sm" name="estado"><option value="APROBADA">Aprobar</option><option value="OBSERVADA">Observar</option></select><button class="btn btn-sm btn-outline-primary">Guardar</button></form></td><?php endif;?></tr><?php endforeach;endif;?></tbody></table></div></div></main><?php require __DIR__.'/../footer.php';?>
